import { useState, useEffect, useCallback } from 'react';
import { BarChart3, ArrowLeft, Search, Download, DollarSign, ShoppingBag, CalendarCheck, AlertTriangle, Lock, Clock, Eye } from 'lucide-react';
import { useNavigate, useParams } from 'react-router-dom';
import { db } from '@/services/firebase/config';
import { collection, query, where, getDocs, addDoc } from 'firebase/firestore';
import { useAuth } from '@/hooks/useAuth';
import { Button, Card, Badge, Input } from '@/components/shared';
import { format, subDays, parseISO } from 'date-fns';
import { es } from 'date-fns/locale';
import { exportDailySalesToExcel } from '@/services/exportExcel';
import type { PettyCashExportItem } from '@/services/exportExcel';
import { getPeruDateString, getPeruNow } from '@/utils/dateUtils';
import { DailyReportPreviewModal } from '@/components/features/DailyReportPreviewModal';

// A "day record" may come from a closure, from raw orders, or both.
interface DayRecord {
    date: string;
    totalSales: number;
    orderCount: number;
    salesByWaiter: Record<string, number>;
    salesByPaymentMethod: Record<string, number>;
    createdByName?: string;
    closureId?: string;              // If undefined → no closure for this day
    closureStatus?: 'open' | 'closed'; // 'open' = session exists but not closed
}

export function ReportesPage() {
    const { user } = useAuth();
    const navigate = useNavigate();
    const { restaurantSlug } = useParams();

    // Date Range State (default: last 7 days)
    const [fromDate, setFromDate] = useState(format(subDays(new Date(), 7), 'yyyy-MM-dd'));
    const [toDate, setToDate] = useState(format(new Date(), 'yyyy-MM-dd'));

    // Data State
    const [dayRecords, setDayRecords] = useState<DayRecord[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isExporting, setIsExporting] = useState(false);
    const [closingDate, setClosingDate] = useState<string | null>(null);
    const [previewRecord, setPreviewRecord] = useState<DayRecord | null>(null);

    // ─── MAIN FETCH ────────────────────────────────────────────────────────────
    // FIX B3: Reads BOTH closures AND raw orders, then merges them.
    // Days with ventas but no closure are shown with a "Sin Cierre" badge.
    const fetchData = useCallback(async () => {
        if (!user?.restaurantId) return;

        setIsLoading(true);
        try {
            // 1. Fetch all closures in range
            const closuresQ = query(
                collection(db, 'closures'),
                where('restaurantId', '==', user.restaurantId),
                where('date', '>=', fromDate),
                where('date', '<=', toDate)
            );
            const closuresSnap = await getDocs(closuresQ);
            const closuresByDate: Record<string, DayRecord> = {};

            closuresSnap.docs.forEach(d => {
                const c = d.data();
                closuresByDate[c.date] = {
                    date: c.date,
                    totalSales: c.totalSales || 0,
                    orderCount: c.orderCount || 0,
                    salesByWaiter: c.salesByWaiter || {},
                    salesByPaymentMethod: c.salesByPaymentMethod || {},
                    createdByName: c.createdByName,
                    closureId: d.id,
                    closureStatus: c.status,
                };
            });

            // 2. OPT: Fetch PAID orders in range using dateStr index
            const ordersQ = query(
                collection(db, 'orders'),
                where('restaurantId', '==', user.restaurantId),
                where('status', '==', 'paid'),
                where('dateStr', '>=', fromDate),
                where('dateStr', '<=', toDate)
            );
            const ordersSnap = await getDocs(ordersQ);

            // Group orders by Peru date
            const ordersByDate: Record<string, { totalSales: number; orderCount: number; salesByWaiter: Record<string, number>; salesByPaymentMethod: Record<string, number>; }> = {};

            ordersSnap.docs.forEach(d => {
                const data = d.data();
                const dateStr = data.dateStr || getPeruDateString(data.createdAt?.toDate ? data.createdAt.toDate() : new Date(data.createdAt));

                if (!ordersByDate[dateStr]) {
                    ordersByDate[dateStr] = { totalSales: 0, orderCount: 0, salesByWaiter: {}, salesByPaymentMethod: {} };
                }
                const entry = ordersByDate[dateStr];
                entry.totalSales += data.total || 0;
                entry.orderCount += 1;

                const waiter = data.userName || 'Desconocido';
                entry.salesByWaiter[waiter] = (entry.salesByWaiter[waiter] || 0) + (data.total || 0);

                if (data.payments && data.payments.length > 0) {
                    data.payments.forEach((p: any) => {
                        const pm = p.method || 'unknown';
                        entry.salesByPaymentMethod[pm] = (entry.salesByPaymentMethod[pm] || 0) + (p.amount || 0);
                    });
                } else {
                    const pm = data.paymentMethod || 'unknown';
                    entry.salesByPaymentMethod[pm] = (entry.salesByPaymentMethod[pm] || 0) + (data.total || 0);
                }
            });

            // 3. Merge: for dates that have orders but NO closure, create a synthetic record
            Object.entries(ordersByDate).forEach(([date, data]) => {
                if (!closuresByDate[date]) {
                    // Day has sales but no closure document — this is the main bug scenario
                    closuresByDate[date] = {
                        date,
                        totalSales: data.totalSales,
                        orderCount: data.orderCount,
                        salesByWaiter: data.salesByWaiter,
                        salesByPaymentMethod: data.salesByPaymentMethod,
                        closureId: undefined,     // No closure
                        closureStatus: undefined, // No session at all
                    };
                } else if (closuresByDate[date].closureStatus === 'open') {
                    // Session exists (open) → update with live order data for accuracy
                    closuresByDate[date].totalSales = data.totalSales;
                    closuresByDate[date].orderCount = data.orderCount;
                    closuresByDate[date].salesByWaiter = data.salesByWaiter;
                    closuresByDate[date].salesByPaymentMethod = data.salesByPaymentMethod;
                }
            });

            // 4. Sort by date descending
            const sorted = Object.values(closuresByDate).sort((a, b) => b.date.localeCompare(a.date));
            setDayRecords(sorted);
        } catch (error) {
            console.error('Error fetching reports:', error);
            alert('Error al cargar reportes. Verifique los índices de Firestore.');
        } finally {
            setIsLoading(false);
        }
    }, [user?.restaurantId, fromDate, toDate]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    // ─── RETROACTIVE CLOSURE ───────────────────────────────────────────────────
    // Pilar 3: Admin can close a past day that has sales but no closed closure.
    const handleRetroactiveClose = async (record: DayRecord) => {
        if (!user?.restaurantId) return;
        if (!confirm(`¿Cerrar caja retroactivamente para el ${format(parseISO(record.date), 'dd/MM/yyyy', { locale: es })}?\n\nEsto registrará las ventas de ese día en el historial de cierres.`)) return;

        setClosingDate(record.date);
        try {
            if (record.closureId) {
                // Session exists (open) → just mark it closed
                const { updateDoc, doc } = await import('firebase/firestore');
                await updateDoc(doc(db, 'closures', record.closureId), {
                    totalSales: record.totalSales,
                    orderCount: record.orderCount,
                    salesByWaiter: record.salesByWaiter,
                    salesByPaymentMethod: record.salesByPaymentMethod,
                    status: 'closed',
                    closedAt: getPeruNow(),
                    retroactiveClosure: true,
                });
            } else {
                // No session at all → create and close right away
                await addDoc(collection(db, 'closures'), {
                    restaurantId: user.restaurantId,
                    date: record.date,
                    openingBalance: 0,
                    totalSales: record.totalSales,
                    orderCount: record.orderCount,
                    salesByWaiter: record.salesByWaiter,
                    salesByPaymentMethod: record.salesByPaymentMethod,
                    expenses: [],
                    status: 'closed',
                    createdAt: getPeruNow(),
                    createdBy: user.id,
                    createdByName: user.name,
                    closedAt: getPeruNow(),
                    retroactiveClosure: true,
                    autoCreated: true,
                });
            }
            await fetchData();
        } catch (err) {
            console.error('Error closing retroactively:', err);
            alert('Error al realizar el cierre retroactivo.');
        } finally {
            setClosingDate(null);
        }
    };

    // ─── EXPORTS ───────────────────────────────────────────────────────────────
    const totalSales = dayRecords.reduce((sum, r) => sum + r.totalSales, 0);
    const totalOrders = dayRecords.reduce((sum, r) => sum + r.orderCount, 0);
    const closedDays = dayRecords.filter(r => r.closureStatus === 'closed').length;

    const handleExportHistorical = async () => {
        if (!user?.restaurantId || dayRecords.length === 0) return;
        setIsExporting(true);
        try {
            // OPT: Use dateStr range filter instead of fetching ALL orders
            const q = query(
                collection(db, 'orders'),
                where('restaurantId', '==', user.restaurantId),
                where('status', '==', 'paid'),
                where('dateStr', '>=', fromDate),
                where('dateStr', '<=', toDate)
            );
            const snapshot = await getDocs(q);

            const orders = snapshot.docs
                .map(d => {
                    const data = d.data();
                    const createdAt = data.createdAt?.toDate ? data.createdAt.toDate() : new Date(data.createdAt);
                    return { id: d.id, ...data, createdAt } as any;
                });

            const summaryMetrics = {
                totalSales,
                orderCount: totalOrders,
                salesByWaiter: {} as Record<string, number>,
                salesByPaymentMethod: {} as Record<string, number>
            };
            dayRecords.forEach(r => {
                Object.entries(r.salesByWaiter || {}).forEach(([w, a]) => {
                    summaryMetrics.salesByWaiter[w] = (summaryMetrics.salesByWaiter[w] || 0) + a;
                });
                Object.entries(r.salesByPaymentMethod || {}).forEach(([m, a]) => {
                    summaryMetrics.salesByPaymentMethod[m] = (summaryMetrics.salesByPaymentMethod[m] || 0) + a;
                });
            });

            // Fetch petty cash expenses for the date range
            const pcQuery = query(
                collection(db, 'pettyCashExpenses'),
                where('restaurantId', '==', user.restaurantId),
                where('date', '>=', fromDate),
                where('date', '<=', toDate)
            );
            const pcSnapshot = await getDocs(pcQuery);
            const pettyCashItems: PettyCashExportItem[] = pcSnapshot.docs
                .filter(d => {
                    const s = d.data().status;
                    return s === 'auto_approved' || s === 'approved';
                })
                .map(d => {
                    const data = d.data();
                    return {
                        category: data.category || 'Otro',
                        description: data.description || '',
                        amount: data.amount || 0,
                        requestedByName: data.requestedByName || 'Desconocido',
                        status: data.status,
                    };
                });

            const periodLabel = `${format(parseISO(fromDate), 'dd/MM/yyyy')} - ${format(parseISO(toDate), 'dd/MM/yyyy')}`;
            await exportDailySalesToExcel(summaryMetrics, orders, periodLabel, pettyCashItems.length > 0 ? pettyCashItems : undefined);
        } catch (err) {
            console.error('Error exporting:', err);
            alert('Error al exportar los datos.');
        } finally {
            setIsExporting(false);
        }
    };

    const handleExportSingleDay = async (record: DayRecord) => {
        if (!user?.restaurantId) return;
        try {
            // OPT: Use dateStr filter for single day export
            const q = query(
                collection(db, 'orders'),
                where('restaurantId', '==', user.restaurantId),
                where('status', '==', 'paid'),
                where('dateStr', '==', record.date)
            );
            const snapshot = await getDocs(q);

            const orders = snapshot.docs
                .map(d => {
                    const data = d.data();
                    const createdAt = data.createdAt?.toDate ? data.createdAt.toDate() : new Date(data.createdAt);
                    return { id: d.id, ...data, createdAt } as any;
                });

            const metrics = {
                totalSales: record.totalSales,
                orderCount: record.orderCount,
                salesByWaiter: record.salesByWaiter || {},
                salesByPaymentMethod: record.salesByPaymentMethod || {}
            };
            // Fetch petty cash expenses for this day
            const pcQuery = query(
                collection(db, 'pettyCashExpenses'),
                where('restaurantId', '==', user.restaurantId),
                where('date', '==', record.date)
            );
            const pcSnapshot = await getDocs(pcQuery);
            const pettyCashItems: PettyCashExportItem[] = pcSnapshot.docs
                .filter(d => {
                    const s = d.data().status;
                    return s === 'auto_approved' || s === 'approved';
                })
                .map(d => {
                    const data = d.data();
                    return {
                        category: data.category || 'Otro',
                        description: data.description || '',
                        amount: data.amount || 0,
                        requestedByName: data.requestedByName || 'Desconocido',
                        status: data.status,
                    };
                });

            await exportDailySalesToExcel(metrics, orders, format(parseISO(record.date), 'dd/MM/yyyy'), pettyCashItems.length > 0 ? pettyCashItems : undefined);
        } catch (err) {
            console.error('Error exporting day:', err);
            alert('Error al exportar el reporte del día.');
        }
    };

    // ─── STATUS BADGE HELPER ───────────────────────────────────────────────────
    const StatusBadge = ({ record }: { record: DayRecord }) => {
        if (record.closureStatus === 'closed') {
            return <Badge variant="success" style={{ fontSize: '0.7rem', padding: '0.2rem 0.6rem', display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}><Lock size={11} /> Cerrada</Badge>;
        }
        if (record.closureStatus === 'open') {
            return <Badge variant="warning" style={{ fontSize: '0.7rem', padding: '0.2rem 0.6rem', display: 'inline-flex', alignItems: 'center', gap: '0.25rem', background: '#fef3c7', color: '#92400e' }}><Clock size={11} /> Abierta</Badge>;
        }
        // No closure at all
        return <Badge variant="error" style={{ fontSize: '0.7rem', padding: '0.2rem 0.6rem', display: 'inline-flex', alignItems: 'center', gap: '0.25rem', background: '#fee2e2', color: '#991b1b' }}><AlertTriangle size={11} /> Sin Cierre</Badge>;
    };

    // ─── RENDER ────────────────────────────────────────────────────────────────
    return (
        <div className="container mt-md">
            <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem', flexWrap: 'wrap', gap: '1rem' }}>
                <div>
                    <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                        <BarChart3 size={32} className="text-primary" /> Reportes Históricos
                    </h1>
                    <p>Ventas por rango de fechas — incluyendo días sin cierre de caja</p>
                </div>
                <Button variant="ghost" onClick={() => navigate(`/${restaurantSlug}/admin`)} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <ArrowLeft size={18} /> Volver
                </Button>
            </header>

            {/* Filter Section */}
            <Card style={{ padding: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap', alignItems: 'flex-end' }}>
                    <div>
                        <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>Desde</label>
                        <Input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} />
                    </div>
                    <div>
                        <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>Hasta</label>
                        <Input type="date" value={toDate} onChange={e => setToDate(e.target.value)} />
                    </div>
                    <Button onClick={fetchData} disabled={isLoading} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        {isLoading ? 'Cargando...' : <><Search size={18} /> Buscar</>}
                    </Button>
                </div>
            </Card>

            {/* Summary Cards */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1.5rem', marginBottom: '2.5rem' }}>
                <Card style={{ padding: '1.75rem', textAlign: 'center', borderTop: '4px solid var(--primary-color)', boxShadow: 'var(--shadow-md)', borderRadius: 'var(--radius-lg)' }}>
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem', marginBottom: '0.75rem', fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                        <DollarSign size={16} /> Total Ventas
                    </div>
                    <div style={{ fontSize: '2.25rem', fontWeight: '900', color: 'var(--text-primary)', letterSpacing: '-0.02em' }}>
                        S/ {totalSales.toFixed(2)}
                    </div>
                </Card>
                <Card style={{ padding: '1.75rem', textAlign: 'center', borderTop: '4px solid var(--success-color)', boxShadow: 'var(--shadow-md)', borderRadius: 'var(--radius-lg)' }}>
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem', marginBottom: '0.75rem', fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                        <ShoppingBag size={16} /> Total Pedidos
                    </div>
                    <div style={{ fontSize: '2.25rem', fontWeight: '900', color: 'var(--success-color)', letterSpacing: '-0.02em' }}>
                        {totalOrders}
                    </div>
                </Card>
                <Card style={{ padding: '1.75rem', textAlign: 'center', borderTop: '4px solid var(--secondary-hover)', boxShadow: 'var(--shadow-md)', borderRadius: 'var(--radius-lg)' }}>
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem', marginBottom: '0.75rem', fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                        <CalendarCheck size={16} /> Días con Cierre
                    </div>
                    <div style={{ fontSize: '2.25rem', fontWeight: '900', color: 'var(--primary-color)', letterSpacing: '-0.02em' }}>
                        {closedDays}
                    </div>
                </Card>
            </div>

            {/* Info Banner for unclosed days */}
            {dayRecords.some(r => r.closureStatus !== 'closed') && (
                <div style={{
                    background: 'rgba(245,158,11,0.08)',
                    border: '1px solid rgba(245,158,11,0.2)',
                    borderLeft: '5px solid #f59e0b',
                    borderRadius: 'var(--radius-md)',
                    padding: '1rem 1.25rem',
                    marginBottom: '1.5rem',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.75rem',
                    color: 'var(--text-primary)',
                    fontSize: '0.9rem'
                }}>
                    <AlertTriangle size={20} style={{ flexShrink: 0, color: '#f59e0b' }} />
                    <span>
                        <strong>Días sin cierre detectados.</strong> Las ventas están guardadas correctamente en el sistema.
                        Usa el botón <strong>"Cerrar Retroactivo"</strong> para regularizar los cierres pendientes.
                    </span>
                </div>
            )}

            {/* Records Table */}
            <Card style={{ padding: '1.5rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', flexWrap: 'wrap', gap: '0.75rem' }}>
                    <h3 style={{ margin: 0 }}>Historial de Ventas</h3>
                    {dayRecords.length > 0 && (
                        <Button
                            variant="secondary"
                            size="sm"
                            onClick={handleExportHistorical}
                            disabled={isExporting}
                            style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}
                        >
                            <Download size={16} /> {isExporting ? 'Generando Excel...' : 'Exportar Todo (Excel)'}
                        </Button>
                    )}
                </div>

                {dayRecords.length === 0 ? (
                    <div style={{ textAlign: 'center', padding: '3rem', color: 'var(--text-secondary)', fontWeight: '600' }}>
                        No se encontraron ventas en el rango seleccionado.
                    </div>
                ) : (
                    <div style={{ overflowX: 'auto' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                            <thead>
                                <tr style={{ borderBottom: '2px solid var(--divider-color)', textAlign: 'left' }}>
                                    <th style={{ padding: '1rem', color: 'var(--text-primary)', fontWeight: '800', fontSize: '0.9rem', textTransform: 'uppercase' }}>Fecha</th>
                                    <th style={{ padding: '1rem', color: 'var(--text-primary)', fontWeight: '800', fontSize: '0.9rem', textTransform: 'uppercase' }}>Estado</th>
                                    <th style={{ padding: '1rem', color: 'var(--text-primary)', fontWeight: '800', fontSize: '0.9rem', textTransform: 'uppercase' }}>Pedidos</th>
                                    <th style={{ padding: '1rem', color: 'var(--text-primary)', fontWeight: '800', fontSize: '0.9rem', textTransform: 'uppercase' }}>Total</th>
                                    <th style={{ padding: '1rem', color: 'var(--text-primary)', fontWeight: '800', fontSize: '0.9rem', textTransform: 'uppercase' }}>Responsable</th>
                                    <th style={{ padding: '1rem', textAlign: 'right' }}>Acciones</th>
                                </tr>
                            </thead>
                            <tbody>
                                {dayRecords.map(record => (
                                    <tr
                                        key={record.date}
                                        style={{ borderBottom: '1px solid var(--divider-color)', transition: 'background-color 0.2s' }}
                                        onMouseEnter={e => e.currentTarget.style.backgroundColor = 'var(--background-color)'}
                                        onMouseLeave={e => e.currentTarget.style.backgroundColor = 'transparent'}
                                    >
                                        <td style={{ padding: '1rem', color: 'var(--text-primary)', fontWeight: '600' }}>
                                            {format(parseISO(record.date), 'dd MMM yyyy', { locale: es })}
                                        </td>
                                        <td style={{ padding: '1rem' }}>
                                            <StatusBadge record={record} />
                                        </td>
                                        <td style={{ padding: '1rem', color: 'var(--text-secondary)', fontWeight: '600' }}>{record.orderCount}</td>
                                        <td style={{ padding: '1rem', color: 'var(--primary-color)', fontWeight: '800', fontSize: '1.1rem' }}>
                                            S/ {record.totalSales.toFixed(2)}
                                        </td>
                                        <td style={{ padding: '1rem', color: 'var(--text-secondary)', fontWeight: '500' }}>
                                            {record.createdByName || (record.closureId ? 'Admin' : '—')}
                                        </td>
                                        <td style={{ padding: '1rem', textAlign: 'right', display: 'flex', gap: '0.5rem', justifyContent: 'flex-end', flexWrap: 'wrap' }}>
                                            <Button
                                                variant="ghost"
                                                size="sm"
                                                onClick={() => setPreviewRecord(record)}
                                                style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem', padding: '0.25rem 0.5rem', color: 'var(--primary-color)' }}
                                                title="Ver Detalle"
                                            >
                                                <Eye size={16} /> Ver
                                            </Button>
                                            <Button
                                                variant="ghost"
                                                size="sm"
                                                onClick={() => handleExportSingleDay(record)}
                                                style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem', padding: '0.25rem 0.5rem' }}
                                                title="Exportar día a Excel"
                                            >
                                                <Download size={16} /> Excel
                                            </Button>
                                            {/* Pilar 3: Retroactive close button for unclosed days (HIDDEN FOR TODAY) */}
                                            {record.closureStatus !== 'closed' && record.orderCount > 0 && record.date !== getPeruDateString() && (
                                                <Button
                                                    variant="secondary"
                                                    size="sm"
                                                    onClick={() => handleRetroactiveClose(record)}
                                                    disabled={closingDate === record.date}
                                                    style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem', padding: '0.25rem 0.6rem', fontSize: '0.75rem' }}
                                                    title="Registrar cierre retroactivo para regularizar este día"
                                                >
                                                    <Lock size={14} /> {closingDate === record.date ? 'Cerrando...' : 'Cerrar Retroactivo'}
                                                </Button>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </Card>

            {/* Preview Modal */}
            {previewRecord && user?.restaurantId && (
                <DailyReportPreviewModal
                    restaurantId={user.restaurantId}
                    record={previewRecord}
                    onClose={() => setPreviewRecord(null)}
                />
            )}
        </div>
    );
}

import type { Restaurant } from '@/types';
import { Crown, Trash2, Calendar, Power, Crown as CrownIcon } from 'lucide-react';
import { Badge, Button } from '@/components/shared';
import { getPeruNow } from '@/utils/dateUtils';
import styles from '../SuperAdmin.module.css';

interface RestaurantCardListProps {
    restaurants: Restaurant[];
    toggleActive: (id: string, currentStatus: boolean) => void;
    toggleDigitalMenu: (id: string, currentStatus: boolean) => void;
    changePlan: (id: string, currentPlan: 'basic' | 'premium', name: string) => void;
    renewSubscription: (id: string) => void;
    handleDelete: (id: string, name: string) => void;
}

export function RestaurantCardList({
    restaurants, toggleActive, toggleDigitalMenu, changePlan, renewSubscription, handleDelete
}: RestaurantCardListProps) {

    const getDaysRemaining = (restaurant: Restaurant) => {
        if (!restaurant.subscriptionEndsAt) return 0;
        const now = getPeruNow();
        const endDate = new Date((restaurant.subscriptionEndsAt as any).seconds ?
            (restaurant.subscriptionEndsAt as any).seconds * 1000 :
            restaurant.subscriptionEndsAt);
        const diffTime = endDate.getTime() - now.getTime();
        return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    };

    return (
        <div className={styles.mobileCardsContainer}>
            {restaurants.map(rest => {
                const days = getDaysRemaining(rest);
                const isExpired = days <= 0;

                return (
                    <div key={rest.id} className={styles.restaurantCard} style={{ borderLeft: `4px solid ${rest.active ? 'var(--success-color)' : 'var(--danger-color)'}` }}>
                        <div className={styles.cardHeader}>
                            <div>
                                <h3 className={styles.cardTitle}>{rest.name}</h3>
                                <a href={`/${rest.id}/login`} target="_blank" rel="noreferrer" style={{ color: 'var(--primary-color)', fontSize: '0.85rem', fontWeight: '700', textDecoration: 'none' }}>
                                    /{rest.id}
                                </a>
                            </div>
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem', alignItems: 'flex-end' }}>
                                <Badge variant={rest.plan === 'premium' ? 'warning' : 'neutral'} style={{ fontSize: '0.7rem' }}>
                                    <span style={{ display: 'flex', alignItems: 'center', gap: '0.2rem' }}>
                                        {rest.plan === 'premium' && <Crown size={10} />}
                                        {(rest.plan || 'basic').toUpperCase()}
                                    </span>
                                </Badge>
                                <Badge variant={rest.active ? 'success' : 'error'} style={{ fontSize: '0.7rem' }}>
                                    {rest.active ? 'ACTIVO' : 'INACTIVO'}
                                </Badge>
                            </div>
                        </div>

                        <div className={styles.cardGrid}>
                            <div className={styles.cardData}>
                                <span className={styles.cardDataLabel}>Días Restantes</span>
                                <span style={{
                                    fontWeight: '800',
                                    color: isExpired ? 'var(--danger-color)' : (days < 5 ? 'var(--warning-color)' : 'var(--success-color)')
                                }}>
                                    {isExpired ? 'VENCIDO' : `${days} días`}
                                </span>
                            </div>

                            <div className={styles.cardData}>
                                <span className={styles.cardDataLabel}>Menú Digital</span>
                                <Badge
                                    variant={rest.features?.digitalMenu ? 'success' : 'neutral'}
                                    style={{ cursor: 'pointer', alignSelf: 'flex-start', fontSize: '0.7rem', border: '1px solid var(--border-color)' }}
                                    onClick={() => toggleDigitalMenu(rest.id, rest.features?.digitalMenu ?? false)}
                                >
                                    {rest.features?.digitalMenu ? '✅ ACTIVO' : '⭕ OFF'}
                                </Badge>
                            </div>
                        </div>

                        <div className={styles.cardActions}>
                            <div style={{ display: 'flex', gap: '0.5rem' }}>
                                <Button
                                    variant={rest.active ? 'outline' : 'primary'}
                                    size="sm"
                                    onClick={() => toggleActive(rest.id, rest.active)}
                                    style={{ flex: 1, fontSize: '0.75rem', fontWeight: '700', padding: '0.5rem' }}
                                >
                                    <Power size={14} style={{ marginRight: '0.25rem' }} />
                                    {rest.active ? 'Apagar' : 'Encender'}
                                </Button>
                                <Button variant="primary" size="sm" onClick={() => renewSubscription(rest.id)} style={{ flex: 1, fontSize: '0.75rem', fontWeight: '700', padding: '0.5rem' }}>
                                    <Calendar size={14} style={{ marginRight: '0.25rem' }} />
                                    Renovar
                                </Button>
                            </div>
                            <div style={{ display: 'flex', gap: '0.5rem' }}>
                                <Button
                                    variant={rest.plan === 'premium' ? 'outline' : 'primary'}
                                    size="sm"
                                    onClick={() => changePlan(rest.id, rest.plan || 'basic', rest.name)}
                                    style={{
                                        flex: 2,
                                        fontSize: '0.75rem',
                                        fontWeight: '800',
                                        padding: '0.5rem',
                                        ...(rest.plan !== 'premium' ? { background: '#d4a017', border: '1px solid #d4a017' } : { border: '1px solid #d4a017', color: '#d4a017' })
                                    }}
                                >
                                    <CrownIcon size={14} style={{ marginRight: '0.25rem' }} />
                                    {rest.plan === 'premium' ? 'Bajar a Basic' : 'Subir a Premium'}
                                </Button>
                                <Button variant="outline" size="sm" onClick={() => handleDelete(rest.id, rest.name)} style={{ flex: 1, fontSize: '0.75rem', fontWeight: '700', padding: '0.5rem', color: 'var(--danger-color)', borderColor: 'var(--danger-color)' }}>
                                    <Trash2 size={14} />
                                </Button>
                            </div>
                        </div>
                    </div>
                );
            })}
            {restaurants.length === 0 && (
                <div style={{ textAlign: 'center', padding: '3rem 1rem', color: 'var(--text-secondary)' }}>
                    No se encontraron restaurantes.
                </div>
            )}
        </div>
    );
}

import type { Restaurant } from '@/types';
import { Smartphone, Crown } from 'lucide-react';
import { Badge, Button } from '@/components/shared';
import { getPeruNow, formatPeruDisplay, ensurePeruDate } from '@/utils/dateUtils';
import styles from '../SuperAdmin.module.css';

interface RestaurantTableProps {
    restaurants: Restaurant[];
    toggleActive: (id: string, currentStatus: boolean) => void;
    toggleDigitalMenu: (id: string, currentStatus: boolean) => void;
    changePlan: (id: string, currentPlan: 'basic' | 'premium', name: string) => void;
    renewSubscription: (id: string) => void;
    handleDelete: (id: string, name: string) => void;
}

export function RestaurantTable({
    restaurants, toggleActive, toggleDigitalMenu, changePlan, renewSubscription, handleDelete
}: RestaurantTableProps) {
    const checkIsExpired = (restaurant: Restaurant) => {
        if (!restaurant.subscriptionEndsAt) return true;
        const endDate = new Date((restaurant.subscriptionEndsAt as any).seconds ?
            (restaurant.subscriptionEndsAt as any).seconds * 1000 :
            restaurant.subscriptionEndsAt);
        return endDate < getPeruNow();
    };

    const getDaysRemaining = (restaurant: Restaurant) => {
        if (!restaurant.subscriptionEndsAt) return 0;
        const now = getPeruNow();
        const endDate = new Date((restaurant.subscriptionEndsAt as any).seconds ?
            (restaurant.subscriptionEndsAt as any).seconds * 1000 :
            restaurant.subscriptionEndsAt);
        const diffTime = endDate.getTime() - now.getTime();
        return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    };

    const formatDate = (date: any) => {
        if (!date) return 'N/A';
        return formatPeruDisplay(ensurePeruDate(date));
    };

    return (
        <div className={styles.tableContainer}>
            <table className={styles.table}>
                <thead>
                    <tr>
                        <th>Restaurante</th>
                        <th>Ruta URL</th>
                        <th>Plan</th>
                        <th>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                                <Smartphone size={14} /> Menú Digital
                            </span>
                        </th>
                        <th>Estado</th>
                        <th>Días Restantes</th>
                        <th>Registro</th>
                        <th>Acciones</th>
                    </tr>
                </thead>
                <tbody>
                    {restaurants.map(rest => {
                        const days = getDaysRemaining(rest);
                        const isExpired = days <= 0;

                        return (
                            <tr key={rest.id}>
                                <td style={{ fontWeight: 'bold' }}>{rest.name}</td>
                                <td>
                                    <a href={`/${rest.id}/login`} target="_blank" rel="noreferrer" style={{ color: 'var(--primary-color)', fontWeight: '700', textDecoration: 'none', borderBottom: '1px dashed' }}>
                                        /{rest.id}
                                    </a>
                                </td>
                                <td>
                                    <Badge variant={rest.plan === 'premium' ? 'warning' : 'neutral'}>
                                        <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                                            {rest.plan === 'premium' && <Crown size={12} />}
                                            {(rest.plan || 'basic').toUpperCase()}
                                        </span>
                                    </Badge>
                                </td>
                                <td>
                                    <Badge
                                        variant={rest.features?.digitalMenu ? 'success' : 'neutral'}
                                        style={{ cursor: 'pointer', userSelect: 'none' }}
                                        onClick={() => toggleDigitalMenu(rest.id, rest.features?.digitalMenu ?? false)}
                                    >
                                        {rest.features?.digitalMenu ? '✅ ACTIVO' : '⭕ OFF'}
                                    </Badge>
                                </td>
                                <td>
                                    <Badge variant={rest.active ? 'success' : 'error'}>
                                        {rest.active ? 'ACTIVO' : 'INACTIVO'}
                                    </Badge>
                                    {checkIsExpired(rest) && (
                                        <Badge variant="error" style={{ marginLeft: '0.5rem' }}>
                                            VENCIDO
                                        </Badge>
                                    )}
                                </td>
                                <td>
                                    <span style={{
                                        fontWeight: 'bold',
                                        color: isExpired ? 'var(--danger-color)' : (days < 5 ? 'var(--warning-color)' : 'var(--success-color)')
                                    }}>
                                        {isExpired ? '0' : days} días
                                    </span>
                                </td>
                                <td style={{ color: 'var(--text-secondary)', fontSize: '0.9rem' }}>
                                    {formatDate(rest.createdAt)}
                                </td>
                                <td>
                                    <div className={styles.actionButtons}>
                                        <Button
                                            variant={rest.active ? 'outline' : 'primary'}
                                            size="sm"
                                            onClick={() => toggleActive(rest.id, rest.active)}
                                            style={{ fontSize: '0.75rem', fontWeight: '800' }}
                                        >
                                            {rest.active ? 'Apagar' : 'Activar'}
                                        </Button>
                                        <Button variant="danger" size="sm" onClick={() => handleDelete(rest.id, rest.name)} style={{ fontSize: '0.75rem', fontWeight: '800' }}>
                                            Eliminar
                                        </Button>
                                        <Button variant="primary" size="sm" onClick={() => renewSubscription(rest.id)} style={{ fontSize: '0.75rem', fontWeight: '800' }}>
                                            Renovar
                                        </Button>
                                        <Button
                                            variant={rest.plan === 'premium' ? 'outline' : 'primary'}
                                            size="sm"
                                            onClick={() => changePlan(rest.id, rest.plan || 'basic', rest.name)}
                                            style={{
                                                fontSize: '0.75rem',
                                                fontWeight: '800',
                                                ...(rest.plan !== 'premium' ? { background: '#d4a017', border: '1px solid #d4a017' } : { border: '1px solid #d4a017', color: '#d4a017' })
                                            }}
                                        >
                                            {rest.plan === 'premium' ? '↓ Basic' : '↑ Premium'}
                                        </Button>
                                    </div>
                                </td>
                            </tr>
                        );
                    })}
                    {restaurants.length === 0 && (
                        <tr>
                            <td colSpan={8} style={{ textAlign: 'center', padding: '2rem', color: 'var(--text-secondary)' }}>
                                No se encontraron restaurantes.
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
        </div>
    );
}

import ExcelJS from 'exceljs';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import type { SalesMetrics } from '@/hooks/useDailySales';
import type { Order } from '@/types';

export interface PettyCashExportItem {
    category: string;
    description: string;
    amount: number;
    requestedByName: string;
    status: string;
}

export const exportDailySalesToExcel = async (
    metrics: SalesMetrics,
    orders: Order[],
    customDateRange?: string,
    pettyCashExpenses?: PettyCashExportItem[]
) => {
    const workbook = new ExcelJS.Workbook();
    workbook.creator = 'Restaurant App';
    workbook.created = new Date();

    const dateStr = customDateRange || format(new Date(), 'dd/MM/yyyy', { locale: es });
    const filename = customDateRange ? `Reporte_Ventas_${customDateRange.replace(/\//g, '-')}.xlsx` : `Ventas_${format(new Date(), 'yyyy-MM-dd')}.xlsx`;

    const paymentLabels: Record<string, string> = {
        cash: 'Efectivo',
        card: 'Tarjeta',
        yape: 'Yape / Plin'
    };

    // ==========================================
    // SHEET 1: RESUMEN
    // ==========================================
    const wsSummary = workbook.addWorksheet('Resumen', {
        views: [{ showGridLines: false }]
    });

    // Title
    wsSummary.mergeCells('A1:B1');
    const titleCell = wsSummary.getCell('A1');
    titleCell.value = customDateRange ? `Reporte de Ventas: ${customDateRange}` : `Resumen de Ventas - ${dateStr}`;
    titleCell.font = { name: 'Arial', size: 16, bold: true, color: { argb: 'FFFFFFFF' } };
    titleCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF2c3e50' } };
    titleCell.alignment = { horizontal: 'center', vertical: 'middle' };
    wsSummary.getRow(1).height = 30;

    // Metrics Table
    wsSummary.getCell('A3').value = 'Métrica';
    wsSummary.getCell('B3').value = 'Valor';

    // Style Headers
    ['A3', 'B3'].forEach(cell => {
        const c = wsSummary.getCell(cell);
        c.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF34495e' } };
        c.border = { bottom: { style: 'thin' } };
    });

    wsSummary.getCell('A4').value = 'Total Ventas';
    wsSummary.getCell('B4').value = metrics.totalSales;
    wsSummary.getCell('B4').numFmt = '"S/" #,##0.00';

    wsSummary.getCell('A5').value = 'Cantidad Pedidos';
    wsSummary.getCell('B5').value = metrics.orderCount;

    // Payment Methods Section
    wsSummary.getCell('A7').value = 'Desglose por Medio de Pago';
    wsSummary.getCell('A7').font = { bold: true, size: 12 };

    let currentRow = 8;
    Object.entries(metrics.salesByPaymentMethod).forEach(([method, amount]) => {
        const label = paymentLabels[method] || (method.charAt(0).toUpperCase() + method.slice(1));
        wsSummary.getCell(`A${currentRow}`).value = label;
        wsSummary.getCell(`B${currentRow}`).value = amount;
        wsSummary.getCell(`B${currentRow}`).numFmt = '"S/" #,##0.00';
        currentRow++;
    });

    // Column Widths
    wsSummary.getColumn('A').width = 30;
    wsSummary.getColumn('B').width = 20;

    // Petty Cash Summary (if provided)
    if (pettyCashExpenses && pettyCashExpenses.length > 0) {
        currentRow += 1;
        wsSummary.getCell(`A${currentRow}`).value = 'Gastos Caja Chica';
        wsSummary.getCell(`A${currentRow}`).font = { bold: true, size: 12 };
        currentRow++;

        const pettyCashTotal = pettyCashExpenses.reduce((sum, e) => sum + e.amount, 0);
        wsSummary.getCell(`A${currentRow}`).value = 'Total Gastos Caja Chica';
        wsSummary.getCell(`B${currentRow}`).value = pettyCashTotal;
        wsSummary.getCell(`B${currentRow}`).numFmt = '"S/" #,##0.00';
        wsSummary.getCell(`B${currentRow}`).font = { bold: true, color: { argb: 'FFFF0000' } };
        currentRow++;

        const cashSales = Object.entries(metrics.salesByPaymentMethod)
            .filter(([m]) => ['cash', 'efectivo'].includes(m.toLowerCase()))
            .reduce((s, [_, a]) => s + a, 0);
        wsSummary.getCell(`A${currentRow}`).value = 'Efectivo Neto (Ventas - Gastos)';
        wsSummary.getCell(`B${currentRow}`).value = cashSales - pettyCashTotal;
        wsSummary.getCell(`B${currentRow}`).numFmt = '"S/" #,##0.00';
        wsSummary.getCell(`B${currentRow}`).font = { bold: true };
    }


    // ==========================================
    // SHEET 2: DETALLE DE PEDIDOS
    // ==========================================
    const wsDetails = workbook.addWorksheet('Detalle Pedidos');

    // Sort orders by date
    const sortedOrders = [...orders].sort((a, b) => {
        const dateA = a.createdAt instanceof Date ? a.createdAt.getTime() : new Date(a.createdAt).getTime();
        const dateB = b.createdAt instanceof Date ? b.createdAt.getTime() : new Date(b.createdAt).getTime();
        return dateA - dateB;
    });

    // Headers
    const headers = ['Fecha', 'Hora', 'Mesa', 'Mozo', 'Items', 'Método Pago', 'Descuento', 'Total'];
    const headerRow = wsDetails.addRow(headers);

    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF2980b9' } };
        cell.alignment = { horizontal: 'center' };
    });

    // Data with Day Grouping
    let lastDateLabel = '';

    sortedOrders.forEach(order => {
        const orderDate = order.createdAt instanceof Date ? order.createdAt : new Date(order.createdAt);
        const currentDateLabel = format(orderDate, 'dd/MM/yyyy');

        // Add a separator row if the date changes (and it's not the first row)
        if (lastDateLabel !== '' && lastDateLabel !== currentDateLabel) {
            const separatorRow = wsDetails.addRow([]);
            separatorRow.height = 5;
            separatorRow.eachCell(cell => {
                cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEEEEEE' } };
            });
        }

        const discountStr = order.discount && order.discount.amount > 0 
            ? `-S/ ${order.discount.amount.toFixed(2)}${order.discount.type === 'percentage' ? ` (${order.discount.value}%)` : ''}`
            : '-';

        const row = wsDetails.addRow([
            currentDateLabel,
            format(orderDate, 'HH:mm'),
            order.tableNumber,
            order.userName || 'N/A',
            order.items.map((i: any) => `${i.quantity}x ${i.productName}`).join(', '),
            order.payments && order.payments.length > 0
                ? order.payments.map((p: any) => `${paymentLabels[p.method] || p.method}: ${p.amount}`).join(', ')
                : (order.paymentMethod ? (paymentLabels[order.paymentMethod] || order.paymentMethod) : '-'),
            discountStr,
            order.total
        ]);

        // Currency Format for Total
        row.getCell(8).numFmt = '"S/" #,##0.00';

        // Alignment for center columns
        [1, 2, 3, 6, 7].forEach(colIndex => {
            row.getCell(colIndex).alignment = { horizontal: 'center' };
        });

        lastDateLabel = currentDateLabel;
    });

    // Auto-filter
    wsDetails.autoFilter = {
        from: 'A1',
        to: { row: 1, column: headers.length }
    };

    // Columns Width
    wsDetails.columns = [
        { width: 12 }, // Fecha
        { width: 10 }, // Hora
        { width: 10 }, // Mesa
        { width: 20 }, // Mozo
        { width: 50 }, // Items
        { width: 15 }, // Payment
        { width: 15 }, // Descuento
        { width: 15 }, // Total
    ];


    // ==========================================
    // SHEET 3: POR MOZO
    // ==========================================
    const wsWaiters = workbook.addWorksheet('Por Mozo');

    const wHeader = wsWaiters.addRow(['Mozo', 'Venta Total']);
    wHeader.eachCell(cell => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF16a085' } };
    });

    Object.entries(metrics.salesByWaiter).forEach(([name, total]) => {
        const row = wsWaiters.addRow([name, total]);
        row.getCell(2).numFmt = '"S/" #,##0.00';
    });

    wsWaiters.getColumn(1).width = 30;
    wsWaiters.getColumn(2).width = 20;


    // ==========================================
    // SHEET 4: GASTOS CAJA CHICA (if provided)
    // ==========================================
    if (pettyCashExpenses && pettyCashExpenses.length > 0) {
        const wsPettyCash = workbook.addWorksheet('Gastos Caja Chica');

        const pcHeader = wsPettyCash.addRow(['Categoría', 'Descripción', 'Monto', 'Solicitado por', 'Estado']);
        pcHeader.eachCell(cell => {
            cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFe67e22' } };
            cell.alignment = { horizontal: 'center' };
        });

        pettyCashExpenses.forEach(expense => {
            const row = wsPettyCash.addRow([
                expense.category,
                expense.description,
                expense.amount,
                expense.requestedByName,
                expense.status === 'auto_approved' ? 'Auto-Aprobado'
                    : expense.status === 'approved' ? 'Aprobado'
                        : expense.status === 'rejected' ? 'Rechazado'
                            : expense.status === 'observed' ? 'Observado'
                                : 'Pendiente'
            ]);
            row.getCell(3).numFmt = '"S/" #,##0.00';
            row.getCell(1).alignment = { horizontal: 'center' };
            row.getCell(5).alignment = { horizontal: 'center' };
        });

        // Total row
        const totalRow = wsPettyCash.addRow(['', 'TOTAL', pettyCashExpenses.reduce((s, e) => s + e.amount, 0), '', '']);
        totalRow.getCell(2).font = { bold: true };
        totalRow.getCell(3).font = { bold: true };
        totalRow.getCell(3).numFmt = '"S/" #,##0.00';

        wsPettyCash.getColumn(1).width = 18;
        wsPettyCash.getColumn(2).width = 40;
        wsPettyCash.getColumn(3).width = 15;
        wsPettyCash.getColumn(4).width = 22;
        wsPettyCash.getColumn(5).width = 16;
    }


    // ==========================================
    // GENERATE FILE
    // ==========================================
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    window.URL.revokeObjectURL(url);
};

import type { Order } from '@/types';

// ESC/POS Commands
const ESC = 0x1B;
const GS = 0x1D;
const LF = 0x0A;

class PrinterService {
    private device: any = null;
    private characteristic: any = null; // For Bluetooth
    private endpointOut: any = null; // For USB
    private ipAddress: string | null = null; // For Network
    private connectionType: 'bluetooth' | 'usb' | 'network' | 'external' | null = null;
    private isAutoPrintEnabled: boolean = localStorage.getItem('printer_auto_print') === 'true';

    constructor() {
        // Restore external (RawBT) connection type from localStorage on app reload
        // Restore network/external (RawBT) connection type from localStorage on app reload
        const savedType = localStorage.getItem('printer_type');
        if (savedType === 'external' || savedType === 'network') {
            this.connectionType = savedType as any;
            this.ipAddress = localStorage.getItem('printer_ip');
        }
    }

    // Bluetooth Connection
    async connectBluetooth() {
        if (!(navigator as any).bluetooth) {
            throw new Error('Web Bluetooth API no está habilitada o soportada en este navegador. Asegúrate de usar Chrome/Edge y HTTPS/localhost.');
        }
        try {
            const device = await (navigator as any).bluetooth.requestDevice({
                filters: [{ services: ['000018f0-0000-1000-8000-00805f9b34fb'] }],
                optionalServices: ['000018f0-0000-1000-8000-00805f9b34fb']
            });

            // Listen for disconnection
            device.addEventListener('gattserverdisconnected', () => {
                console.warn('Bluetooth device disconnected');
                this.device = null;
                this.characteristic = null;
                if (this.connectionType === 'bluetooth') {
                    this.connectionType = null;
                    localStorage.removeItem('printer_type');
                    localStorage.removeItem('printer_name');
                }
            });

            const server = await device.gatt.connect();
            const service = await server.getPrimaryService('000018f0-0000-1000-8000-00805f9b34fb');
            const characteristic = await service.getCharacteristic('00002af1-0000-1000-8000-00805f9b34fb');

            this.device = device;
            this.characteristic = characteristic;
            this.connectionType = 'bluetooth';

            this.saveDevicePreference('bluetooth', device.name || 'Impresora BLE');
            return true;
        } catch (error) {
            console.error('Bluetooth connection error:', error);
            throw error;
        }
    }

    // USB Connection
    async connectUSB() {
        try {
            const device = await (navigator as any).usb.requestDevice({ filters: [] });
            await device.open();
            await device.selectConfiguration(1);

            const iface = device.configuration.interfaces[0];
            await device.claimInterface(iface.interfaceNumber);

            const endpoint = iface.alternate.endpoints.find((e: any) => e.direction === 'out' && e.type === 'bulk');

            if (!endpoint) throw new Error('No bulk out endpoint found');

            this.device = device;
            this.endpointOut = endpoint;
            this.connectionType = 'usb';

            this.saveDevicePreference('usb', device.productName || 'Impresora USB');
            return true;
        } catch (error) {
            console.error('USB connection error:', error);
            throw error;
        }
    }

    // Network Connection (TCP via RawBT bridge or future proxy)
    async connectNetwork(ip: string) {
        if (!ip || !ip.match(/^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/)) {
            throw new Error('Dirección IP no válida. Formato: 192.168.1.100');
        }
        this.ipAddress = ip;
        this.connectionType = 'network';
        this.saveDevicePreference('network', `Impresora Red (${ip})`);
        localStorage.setItem('printer_ip', ip);
        return true;
    }

    // External Bridge (RawBT)
    async connectExternal() {
        this.connectionType = 'external';
        this.saveDevicePreference('external', 'App RawBT (Android)');
        return true;
    }

    private saveDevicePreference(type: 'bluetooth' | 'usb' | 'network' | 'external', name: string) {
        localStorage.setItem('printer_type', type);
        localStorage.setItem('printer_name', name);
    }

    get isConnected(): boolean {
        if (this.connectionType === 'external' || this.connectionType === 'network') {
            return true; // Bridges are fire-and-forget, always "connected"
        }
        if (this.connectionType === 'bluetooth') {
            return !!(this.device?.gatt?.connected && this.characteristic);
        }
        if (this.connectionType === 'usb') {
            return !!(this.device?.opened);
        }
        // Check localStorage only for external/RawBT/Network
        const savedType = localStorage.getItem('printer_type');
        if (savedType === 'external' || savedType === 'network') {
            this.connectionType = savedType as any;
            return true;
        }
        return false;
    }

    get connectedDeviceName() {
        if (!this.isConnected) return 'Ninguno';
        return localStorage.getItem('printer_name') || 'Ninguno';
    }

    get activeConnectionType(): 'bluetooth' | 'usb' | 'network' | 'external' | null {
        if (this.connectionType) return this.connectionType;
        // Only restore external/network from localStorage
        const savedType = localStorage.getItem('printer_type');
        if (savedType === 'external' || savedType === 'network') {
            this.connectionType = savedType as any;
            return savedType as any;
        }
        return null;
    }

    setAutoPrint(enabled: boolean) {
        this.isAutoPrintEnabled = enabled;
        localStorage.setItem('printer_auto_print', String(enabled));
    }

    get autoPrint() {
        return this.isAutoPrintEnabled;
    }

    async disconnect() {
        try {
            if (this.connectionType === 'bluetooth' && this.device?.gatt?.connected) {
                await this.device.gatt.disconnect();
            } else if (this.connectionType === 'usb' && this.device?.opened) {
                await this.device.close();
            }
        } catch (e) {
            console.warn('Error during disconnect:', e);
        }
        this.device = null;
        this.characteristic = null;
        this.endpointOut = null;
        this.connectionType = null;
        localStorage.removeItem('printer_type');
        localStorage.removeItem('printer_name');
    }

    // Print logic
    async printOrder(order: Order) {
        this.ensureConnected();
        const data = this.encodeOrder(order);
        await this.sendData(data);
    }

    // POS Receipt print
    async printReceipt(order: Order, restaurantName: string) {
        this.ensureConnected();
        const data = this.encodeReceipt(order, restaurantName);
        await this.sendData(data);
    }

    async testPrint() {
        this.ensureConnected();
        const encoder = new TextEncoder();
        let data = new Uint8Array([
            ESC, 0x40, // Initialize
            ESC, 0x61, 0x01, // Center
            ...encoder.encode("PRUEBA DE IMPRESION\n"),
            ...encoder.encode("--------------------------------\n"),
            ...encoder.encode("Si ves esto, la conexion\nes correcta.\n"),
            ...encoder.encode("¡Listo para trabajar!\n"),
            ...encoder.encode("--------------------------------\n"),
            LF, LF, LF, LF,
            GS, 0x56, 0x41, 0x03 // Cut
        ]);
        await this.sendData(data);
    }

    private ensureConnected() {
        const type = this.activeConnectionType;
        if (!type) {
            throw new Error('La impresora no está conectada. Ve a Configuración > Impresora para conectarla.');
        }
        if (type === 'bluetooth' && (!this.device?.gatt?.connected || !this.characteristic)) {
            // Clean up stale localStorage
            this.connectionType = null;
            localStorage.removeItem('printer_type');
            localStorage.removeItem('printer_name');
            throw new Error('La conexión Bluetooth se perdió. Reconecta la impresora desde Configuración.');
        }
        if (type === 'usb' && !this.device?.opened) {
            this.connectionType = null;
            localStorage.removeItem('printer_type');
            localStorage.removeItem('printer_name');
            throw new Error('La conexión USB se perdió. Reconecta la impresora desde Configuración.');
        }
        if (type === 'network' && !this.ipAddress) {
            throw new Error('IP de impresora no configurada.');
        }
    }

    private encodeOrder(order: Order): Uint8Array {
        const encoder = new TextEncoder();
        const chunks: Uint8Array[] = [];

        const add = (bytes: number[] | Uint8Array) => chunks.push(new Uint8Array(bytes));
        const addText = (text: string) => add(encoder.encode(text));

        // Initialize
        add([ESC, 0x40]);

        // Header
        add([ESC, 0x61, 0x01]); // Center
        add([GS, 0x21, 0x11]); // Double Size
        addText(`COMANDA ${order.dailyNumber || ''}\n`);
        add([GS, 0x21, 0x00]); // Normal Size

        add([ESC, 0x61, 0x00]); // Left
        addText(`Mesa: ${order.tableNumber === 0 ? 'Para Llevar' : order.tableNumber}\n`);
        addText(`Cliente: ${order.customerName || 'N/A'}\n`);
        addText(`Mozo: ${order.userName}\n`);
        addText(`Fecha: ${order.createdAt.toLocaleString()}\n`);
        addText("--------------------------------\n");

        // Items
        add([ESC, 0x45, 0x01]); // Bold on (ESC E 1)
        order.items.forEach(item => {
            const qtyText = `${item.quantity}x `.padEnd(4);
            const nameText = item.productName.substring(0, 28) + "\n";
            addText(qtyText + nameText);

            // Turn off bold for options and notes
            add([ESC, 0x45, 0x00]);

            if (item.selectedOptions && item.selectedOptions.length > 0) {
                item.selectedOptions.forEach(opt => {
                    const priceText = opt.price ? ` (+${opt.price.toFixed(2)})` : '';
                    addText(`  - ${opt.modifierName}: ${opt.optionName}${priceText}\n`);
                });
            }

            if (item.notes) {
                addText(`  Obs: ${item.notes}\n`);
            }

            // Turn bold back on for next item
            add([ESC, 0x45, 0x01]);
        });
        add([ESC, 0x45, 0x00]); // Bold off

        addText("--------------------------------\n");
        add([ESC, 0x61, 0x02]); // Right
        addText(`TOTAL: S/ ${order.total.toFixed(2)}\n`);

        // Footer
        add([ESC, 0x61, 0x01]); // Center
        addText("\nOrdayGo\n");
        add([LF, LF, LF, LF]);
        add([GS, 0x56, 0x41, 0x03]); // Cut

        return this.combineChunks(chunks);
    }

    private encodeReceipt(order: Order, restaurantName: string): Uint8Array {
        const encoder = new TextEncoder();
        const chunks: Uint8Array[] = [];

        const add = (bytes: number[] | Uint8Array) => chunks.push(new Uint8Array(bytes));
        const addText = (text: string) => add(encoder.encode(text));
        const LINE = "================================\n";

        const paymentLabels: Record<string, string> = {
            cash: 'EFECTIVO',
            yape: 'YAPE / PLIN',
            card: 'TARJETA'
        };

        const now = new Date();
        const dateStr = now.toLocaleDateString('es-PE', { day: '2-digit', month: '2-digit', year: 'numeric' });
        const timeStr = now.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' });

        // Initialize printer
        add([ESC, 0x40]);

        // ── Restaurant Header ──
        add([ESC, 0x61, 0x01]); // Center
        add([GS, 0x21, 0x11]); // Double size
        addText(`${restaurantName.toUpperCase()}\n`);
        add([GS, 0x21, 0x00]); // Normal size
        addText("\n");
        addText(LINE);

        // ── Receipt Title ──
        add([ESC, 0x45, 0x01]); // Bold
        addText("NOTA DE VENTA\n");
        add([ESC, 0x45, 0x00]); // Bold off
        addText(LINE);

        // ── Order Info ──
        add([ESC, 0x61, 0x00]); // Left align
        addText(`Fecha: ${dateStr}  Hora: ${timeStr}\n`);
        addText(`${order.orderType === 'takeout' ? 'PARA LLEVAR' : `Mesa: ${order.tableNumber}`}\n`);
        if (order.customerName) {
            addText(`Cliente: ${order.customerName}\n`);
        }
        addText(`Atendido: ${order.userName}\n`);
        addText(LINE);

        // ── Items Header ──
        add([ESC, 0x45, 0x01]); // Bold
        addText("CANT  DESCRIPCION       IMPORTE\n");
        add([ESC, 0x45, 0x00]); // Bold off
        addText("--------------------------------\n");

        // ── Items ──
        order.items.forEach(item => {
            const qty = `${item.quantity}`.padStart(2);
            const name = item.productName.substring(0, 18).padEnd(18);
            const subtotal = `${item.subtotal.toFixed(2)}`.padStart(8);
            addText(`${qty}   ${name} ${subtotal}\n`);

            // Print options
            if (item.selectedOptions && item.selectedOptions.length > 0) {
                item.selectedOptions.forEach(opt => {
                    const priceText = opt.price ? ` (+${opt.price.toFixed(2)})` : '';
                    let optText = `   - ${opt.modifierName}: ${opt.optionName}${priceText}`;
                    if (optText.length > 32) optText = optText.substring(0, 31);
                    addText(`${optText}\n`);
                });
            }

            // Unit price when quantity > 1
            if (item.quantity > 1) {
                const unitLine = `      c/u S/${item.price.toFixed(2)}`;
                addText(`${unitLine}\n`);
            }
        });

        addText(LINE);

        // ── Total ──
        add([ESC, 0x61, 0x02]); // Right align

        if (order.discount && order.discount.amount > 0) {
            add([GS, 0x21, 0x00]); // Normal size for subtotal
            addText(`SUBTOTAL: S/ ${order.subtotal?.toFixed(2) || (order.total + order.discount.amount).toFixed(2)}\n`);

            add([ESC, 0x45, 0x01]); // Bold
            const descType = order.discount.type === 'percentage' ? `(${order.discount.value}%)` : '';
            addText(`DSCTO ${descType}: -S/ ${order.discount.amount.toFixed(2)}\n`);
            add([ESC, 0x45, 0x00]); // Bold off
            addText("--------------------------------\n");
        }

        add([GS, 0x21, 0x11]); // Double size
        addText(`TOTAL: S/ ${order.total.toFixed(2)}\n`);
        add([GS, 0x21, 0x00]); // Normal size
        addText("\n");

        // ── Payment Method ──
        add([ESC, 0x61, 0x01]); // Center
        add([ESC, 0x45, 0x01]); // Bold
        if (order.payments && order.payments.length > 0) {
            order.payments.forEach(p => {
                addText(`PAGO ${paymentLabels[p.method] || p.method.toUpperCase()}: S/ ${p.amount.toFixed(2)}\n`);
            });
        } else if (order.paymentMethod) {
            addText(`Pagado con: ${paymentLabels[order.paymentMethod] || order.paymentMethod.toUpperCase()}\n`);
        }
        add([ESC, 0x45, 0x00]); // Bold off
        addText(LINE);

        // ── Footer ──
        addText("\n");
        addText("¡Gracias por su preferencia!\n");
        addText("Vuelva pronto\n");
        addText("\n");
        addText("Powered by OrdayGo\n");

        // Feed + Cut
        add([LF, LF, LF, LF]);
        add([GS, 0x56, 0x41, 0x03]);

        return this.combineChunks(chunks);
    }

    private combineChunks(chunks: Uint8Array[]): Uint8Array {
        let totalLength = chunks.reduce((acc, c) => acc + c.length, 0);
        let result = new Uint8Array(totalLength);
        let offset = 0;
        for (let chunk of chunks) {
            result.set(chunk, offset);
            offset += chunk.length;
        }
        return result;
    }

    private async sendData(data: Uint8Array) {
        const type = this.activeConnectionType;

        if (type === 'bluetooth') {
            if (!this.characteristic) {
                throw new Error('La conexión Bluetooth se perdió. Reconecta la impresora.');
            }
            const CHUNK_SIZE = 20;
            for (let i = 0; i < data.length; i += CHUNK_SIZE) {
                const chunk = data.slice(i, i + CHUNK_SIZE);
                await this.characteristic.writeValue(chunk);
            }
        } else if (type === 'usb') {
            if (!this.device) await this.connectUSB();
            await this.device.transferOut(this.endpointOut.endpointNumber, data);
        } else if (type === 'network') {
            this.sendToRawBT(data, this.ipAddress);
        } else if (type === 'external') {
            this.sendToRawBT(data);
        } else {
            throw new Error('No hay método de impresión configurado.');
        }
    }

    private sendToRawBT(data: Uint8Array, ip?: string | null) {
        try {
            // Convert binary data to base64
            let binary = '';
            for (let i = 0; i < data.length; i++) {
                binary += String.fromCharCode(data[i]);
            }
            const base64 = btoa(binary);

            // Build the RawBT intent URL
            // If ip is provided, RawBT will try to connect to that network address
            const networkParam = ip ? `&address=${ip}` : '';
            const url = `intent:base64,${base64}#Intent;scheme=rawbt;package=ru.a402d.rawbtprinter${networkParam};end;`;

            // Use a temporary link element instead of window.location.href
            // This prevents navigating away from the app and losing state
            const link = document.createElement('a');
            link.href = url;
            link.style.display = 'none';
            document.body.appendChild(link);
            link.click();

            // Clean up the link after a short delay
            setTimeout(() => {
                if (link.parentNode) {
                    document.body.removeChild(link);
                }
            }, 100);
        } catch (err: any) {
            console.error('Error en RawBT:', err);
            throw new Error('Error al enviar a RawBT: ' + (err.message || 'Desconocido'));
        }
    }
}

